"use client";

import { motion, useReducedMotion } from "motion/react";
import type { ComponentProps } from "react";

export type SkeletonShimmerPrimitiveProps = ComponentProps<typeof motion.div>;

export function SkeletonShimmerPrimitive({ children, ...props }: SkeletonShimmerPrimitiveProps) {
  const reduceMotion = useReducedMotion();

  return (
    <motion.div
      {...props}
      initial={reduceMotion ? false : {backgroundPosition: "120% 0"}}
      animate={{backgroundPosition: "-120% 0"}}
      transition={reduceMotion ? { duration: 0.12 } : { duration: 1.4, ease: [0.23, 1, 0.32, 1] }}

    >
      {children}
    </motion.div>
  );
}
